package uav.mec;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Random;

/** One episode input: model + device layout (layout seed) + task list (task seed). Immutable.
 * v2.1 levers (MODEL_V21.md) use their own random streams; with every lever off the v2.0 streams are drawn
 * in exactly the v2.0 order, so v2.0 episodes are unchanged.
 */
public record Scenario(MecModel model, long layoutSeed, long taskSeed, List<Device> devices, List<Task> tasks) {

    /** taskWeight = share of all tasks generated by this device; NaN = uniform (v2.0). */
    public record Device(int id, double x, double y, MecModel.DeviceType type, double batteryJ, double taskWeight) {
        public Device(int id, double x, double y, MecModel.DeviceType type, double batteryJ) {
            this(id, x, y, type, batteryJ, Double.NaN);
        }
    }

    /** cycles = actual Gcycles (kernel only); estCycles = what policies see. Deadline is absolute. */
    public record Task(long id, int classIndex, String cls, int device, double arrival, double inputBytes,
                       double cycles, double estCycles, double resultBytes, double deadline, int priority) {
        public Task {
            if (!(arrival >= 0 && inputBytes >= 0 && resultBytes >= 0 && cycles > 0 && estCycles > 0 && deadline > arrival))
                throw new IllegalArgumentException("invalid task " + id);
        }
    }

    public Scenario {
        devices = List.copyOf(devices); tasks = List.copyOf(tasks);
    }

    public static Scenario generate(MecModel m, long layoutSeed, long taskSeed) {
        var layout = layout(m, layoutSeed);
        return new Scenario(m, layoutSeed, taskSeed, layout, tasks(m, taskSeed, layout));
    }

    static List<Device> layout(MecModel m, long seed) {
        Random pos = Seeds.random(seed, "layout/position"), type = Seeds.random(seed, "layout/type"),
                battery = Seeds.random(seed, "layout/battery");
        double total = m.deviceTypes().stream().mapToDouble(MecModel.DeviceType::weight).sum();
        List<Device> out = new ArrayList<>();
        for (int i = 0; i < m.devices(); i++) {
            double x = m.areaM() * pos.nextDouble(), y = m.areaM() * pos.nextDouble();
            var t = pick(m.deviceTypes(), MecModel.DeviceType::weight, total, type.nextDouble());
            double b = t.batteryMinJ() + (t.batteryMaxJ() - t.batteryMinJ()) * battery.nextDouble();
            if (m.initialCharge() != 1) b *= m.initialCharge();
            out.add(new Device(i, x, y, t, b));
        }
        if (m.hotspots() != null) out = hotspots(m, seed, out);
        return out;
    }

    /** L4: a clustered subset of devices that generates taskShare of all tasks. */
    private static List<Device> hotspots(MecModel m, long seed, List<Device> base) {
        Random h = Seeds.random(seed, "layout/hotspot");
        int n = base.size(), k = (int) Math.ceil(m.hotspots().deviceShare() * n);
        if (k >= n) throw new IllegalArgumentException("hotspot share leaves no other device");
        var ids = new ArrayList<Integer>();
        for (int i = 0; i < n; i++) ids.add(i);
        Collections.shuffle(ids, h);
        var hot = new java.util.HashSet<>(ids.subList(0, k));
        double a = m.areaM(), cx = a * (0.125 + 0.75 * h.nextDouble()), cy = a * (0.125 + 0.75 * h.nextDouble());
        var out = new ArrayList<Device>();
        for (var d : base) {
            double share = hot.contains(d.id()) ? m.hotspots().taskShare() / k : (1 - m.hotspots().taskShare()) / (n - k);
            if (!hot.contains(d.id())) { out.add(new Device(d.id(), d.x(), d.y(), d.type(), d.batteryJ(), share)); continue; }
            double r = a / 8 * Math.sqrt(h.nextDouble()), ang = 2 * Math.PI * h.nextDouble();
            double x = Math.max(0, Math.min(a, cx + r * Math.cos(ang))), y = Math.max(0, Math.min(a, cy + r * Math.sin(ang)));
            out.add(new Device(d.id(), x, y, d.type(), d.batteryJ(), share));
        }
        return out;
    }

    static List<Task> tasks(MecModel m, long seed, List<Device> layout) {
        Random arrivals = Seeds.random(seed, "task/arrival"), device = Seeds.random(seed, "task/device"),
                cls = Seeds.random(seed, "task/class"), bytes = Seeds.random(seed, "task/input-bytes"),
                cycles = Seeds.random(seed, "task/cycles"), estimate = Seeds.random(seed, "task/estimate"),
                result = Seeds.random(seed, "task/result-bytes"), deadline = Seeds.random(seed, "task/deadline");
        double rate = m.totalArrivalRate(layout), total = m.classes().stream().mapToDouble(MecModel.TaskClass::weight).sum();
        var bursts = m.bursts();
        Random burst = bursts == null ? null : Seeds.random(seed, "task/burst");
        boolean high = bursts != null && burst.nextDouble() < bursts.highProbability();
        double switchAt = bursts == null ? Double.POSITIVE_INFINITY : dwell(burst, bursts, high);
        List<Task> out = new ArrayList<>();
        double t = 0;
        while (true) {
            double now = bursts == null ? rate : rate * (high ? bursts.highRate() : bursts.lowRate());
            double gap = -Math.log1p(-arrivals.nextDouble()) / now;
            if (t + gap >= switchAt) { // memoryless: restart the gap at the state change
                t = switchAt; high = !high; switchAt = t + dwell(burst, bursts, high);
                if (t >= m.arrivalWindowS()) break;
                continue;
            }
            t += gap;
            if (t >= m.arrivalWindowS()) break;
            if (out.size() >= 2_000_000) throw new IllegalArgumentException("too many tasks");
            int d = m.hotspots() == null ? device.nextInt(m.devices()) : weighted(layout, device.nextDouble());
            int k = indexOf(m.classes(), MecModel.TaskClass::weight, total, cls.nextDouble());
            var c = m.classes().get(k);
            double actual = Math.max(1e-9, c.cycles().sample(cycles));
            double est = Math.max(1e-9, actual * (1 + m.estimateError() * (2 * estimate.nextDouble() - 1)));
            double due = t + Math.max(1e-6, c.deadlineS().sample(deadline));
            out.add(new Task(out.size(), k, c.name(), d, t, c.inputBytes().sample(bytes), actual, est,
                    c.resultBytes().sample(result), due, c.priority()));
        }
        out.sort(Comparator.comparingDouble(Task::arrival).thenComparingLong(Task::id));
        return out;
    }

    private static double dwell(Random r, MecModel.Bursts b, boolean high) {
        return -Math.log1p(-r.nextDouble()) * (high ? b.highMeanS() : b.lowMeanS());
    }

    private static int weighted(List<Device> layout, double u) {
        double acc = 0;
        for (var d : layout) {
            acc += d.taskWeight();
            if (u < acc) return d.id();
        }
        return layout.get(layout.size() - 1).id();
    }

    private static <T> T pick(List<T> items, java.util.function.ToDoubleFunction<T> weight, double total, double u) {
        return items.get(indexOf(items, weight, total, u));
    }

    private static <T> int indexOf(List<T> items, java.util.function.ToDoubleFunction<T> weight, double total, double u) {
        double acc = 0;
        for (int i = 0; i < items.size(); i++) {
            acc += weight.applyAsDouble(items.get(i)) / total;
            if (u < acc) return i;
        }
        return items.size() - 1;
    }

    /** SHA-256 of the task list and layout: equal hashes mean policies saw the same episode input. */
    public String hash() {
        var s = new StringBuilder();
        for (var d : devices) {
            s.append(d.id()).append(',').append(d.x()).append(',').append(d.y()).append(',')
                    .append(d.type().name()).append(',').append(d.batteryJ());
            if (!Double.isNaN(d.taskWeight())) s.append(",w").append(d.taskWeight()); // v2.0 rows unchanged
            s.append('\n');
        }
        for (var t : tasks) s.append(t.id()).append(',').append(t.cls()).append(',').append(t.device()).append(',')
                .append(t.arrival()).append(',').append(t.inputBytes()).append(',').append(t.cycles()).append(',')
                .append(t.estCycles()).append(',').append(t.resultBytes()).append(',').append(t.deadline()).append('\n');
        return Seeds.sha256Hex(s.toString());
    }
}
